// ---- FLEET PULSE — entry point --------------------------------------------
// status-data.json is generated by scripts/status-build.mjs from STATUS.yaml.
// This page renders whichever schema the snapshot actually declares:
//   schema: 2  -> the Fleet Pulse v2 mission-control board (fleet-pulse.tsx)
//   anything else -> the legacy schema-1 view (legacy-view.tsx), defensive —
//                    the board never crashes on an old or partial snapshot.
import rawStatus from "./status-data.json";
import FleetPulse from "./fleet-pulse";
import LegacyView from "./legacy-view";
import { isSchema2 } from "./schema";

export default function Home() {
  const data: unknown = rawStatus;
  if (isSchema2(data)) return <FleetPulse data={data} />;
  return <LegacyView data={data} />;
}
